package com.ecotrack.backend.gamification; import jakarta.persistence.*; @Entity @Table(name="badges") public class Badge{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;String name,description,criteria;int points;public Long getId(){return id;}public String getName(){return name;}public String getDescription(){return description;}public String getCriteria(){return criteria;}public int getPoints(){return points;}}
